import fs from "fs-extra";
import path from "path";
import { readConfiguredPlatforms } from "./config-platforms.js";

/** Managed block inserted into single-file agent contexts (Gemini, Codex). */
export const MARKER_START = "<!-- ai-sdlc-framework:start -->";
export const MARKER_END = "<!-- ai-sdlc-framework:end -->";

const BUNDLE_HEADER =
  "This section is generated by [AI-SDLC Framework](https://www.npmjs.com/package/@tbarreno/ai-sdlc-framework). Run `npx @tbarreno/ai-sdlc-framework update` to refresh.";

async function listMdcFiles(dir) {
  if (!(await fs.pathExists(dir))) return [];
  const names = (await fs.readdir(dir)).filter((n) => n.endsWith(".mdc")).sort();
  const files = [];
  for (const name of names) {
    files.push({
      name,
      baseName: name.replace(/\.mdc$/, ""),
      content: await fs.readFile(path.join(dir, name), "utf-8"),
    });
  }
  return files;
}

function stripFrontmatter(content) {
  if (!content.startsWith("---")) return content;
  const end = content.indexOf("---", 3);
  if (end === -1) return content;
  return content.slice(end + 3).trimStart();
}

function buildBundledMarkdown(rules, commands) {
  const parts = [
    BUNDLE_HEADER,
    "",
    "Always read `docs/config.yaml` at the start of any SDLC task.",
    "",
  ];

  for (const rule of rules) {
    parts.push(`## Rule: ${rule.baseName}`, "", stripFrontmatter(rule.content), "");
  }

  parts.push("## SDLC slash workflows", "");
  parts.push(
    "Use these workflows when the user invokes `/sdlc-*` or asks to run a methodology phase.",
    "",
  );

  for (const command of commands) {
    parts.push(stripFrontmatter(command.content), "", "---", "");
  }

  return parts.join("\n").trim();
}

async function upsertMarkedSection(filePath, innerMarkdown) {
  const block = `${MARKER_START}\n${innerMarkdown}\n${MARKER_END}`;
  const dir = path.dirname(filePath);
  await fs.ensureDir(dir);

  if (await fs.pathExists(filePath)) {
    let existing = await fs.readFile(filePath, "utf-8");
    const pattern = new RegExp(
      `${MARKER_START.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[\\s\\S]*?${MARKER_END.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`,
    );
    if (pattern.test(existing)) {
      existing = existing.replace(pattern, block);
    } else {
      existing = `${existing.trimEnd()}\n\n${block}\n`;
    }
    await fs.writeFile(filePath, existing, "utf-8");
  } else {
    await fs.writeFile(
      filePath,
      `# AI-SDLC Framework\n\n${block}\n`,
      "utf-8",
    );
  }
}

async function removeLegacySdlcArtifacts(destDir) {
  const existing = await fs.readdir(destDir).catch(() => []);
  for (const name of existing) {
    if (
      name.startsWith("sdlc-") &&
      (name.endsWith(".md") || name.endsWith(".mdc"))
    ) {
      await fs.remove(path.join(destDir, name));
    }
  }
}

async function writeMdcAsMdFiles(artifacts, destDir) {
  await fs.ensureDir(destDir);
  await removeLegacySdlcArtifacts(destDir);
  for (const file of artifacts) {
    await fs.writeFile(
      path.join(destDir, `${file.baseName}.md`),
      file.content,
      "utf-8",
    );
  }
}

async function syncCursor(projectRoot, rules, commands) {
  const rulesDir = path.join(projectRoot, ".cursor/rules");
  await removeLegacySdlcArtifacts(rulesDir);
  await copyMdcTree(rules, rulesDir);
  await writeMdcAsMdFiles(commands, path.join(projectRoot, ".cursor/commands"));
}

async function copyMdcTree(artifacts, destDir) {
  await fs.ensureDir(destDir);
  for (const file of artifacts) {
    await fs.writeFile(path.join(destDir, file.name), file.content, "utf-8");
  }
}

async function syncClaude(projectRoot, rules, commands) {
  await writeMdcAsMdFiles(rules, path.join(projectRoot, ".claude/rules"));
  await writeMdcAsMdFiles(commands, path.join(projectRoot, ".claude/commands"));
}

async function syncGemini(projectRoot, bundle) {
  await upsertMarkedSection(path.join(projectRoot, "GEMINI.md"), bundle);

  const geminiMetaDir = path.join(projectRoot, ".gemini");
  await fs.ensureDir(geminiMetaDir);

  const legacy = (await fs.readdir(geminiMetaDir).catch(() => [])).filter((n) =>
    n.endsWith(".mdc"),
  );
  for (const name of legacy) {
    await fs.remove(path.join(geminiMetaDir, name));
  }

  await fs.writeFile(
    path.join(geminiMetaDir, "README.md"),
    `# Gemini CLI — AI-SDLC

Project instructions for Gemini CLI are maintained in the repository root **\`GEMINI.md\`** (managed block between \`${MARKER_START}\` markers).

- Reload context: \`/memory reload\` in Gemini CLI after \`ai-sdlc update\`.
- Optional: add \`GEMINI.md\` to \`context.fileName\` in Gemini settings if you use a custom context filename.
`,
    "utf-8",
  );
}

async function syncOpenAi(projectRoot, rules, commands, bundle) {
  await upsertMarkedSection(path.join(projectRoot, "AGENTS.md"), bundle);

  const openAiDir = path.join(projectRoot, ".openai");
  await fs.ensureDir(openAiDir);

  const legacy = (await fs.readdir(openAiDir).catch(() => [])).filter((n) =>
    n.endsWith(".mdc"),
  );
  for (const name of legacy) {
    await fs.remove(path.join(openAiDir, name));
  }

  await fs.writeFile(
    path.join(openAiDir, "instructions.md"),
    `# AI-SDLC — ChatGPT / Codex instructions\n\n${bundle}\n`,
    "utf-8",
  );

  await writeMdcAsMdFiles(commands, path.join(openAiDir, "commands"));
  await writeMdcAsMdFiles(rules, path.join(openAiDir, "rules"));

  await fs.writeFile(
    path.join(openAiDir, "README.md"),
    `# OpenAI / ChatGPT — AI-SDLC

## Codex CLI & IDE

Codex loads **\`AGENTS.md\`** at the repository root (managed block between \`${MARKER_START}\` markers).

## ChatGPT Projects (web)

ChatGPT Projects do not read local folders automatically. Copy the contents of \`.openai/instructions.md\` into **Project settings → Instructions**, or upload command files from \`.openai/commands/\` as project knowledge.

## Files

| Path | Purpose |
| :--- | :--- |
| \`AGENTS.md\` | Primary instructions for Codex |
| \`.openai/instructions.md\` | Same bundle for copy/paste into ChatGPT Projects |
| \`.openai/commands/*.md\` | Per-phase workflow reference |
| \`.openai/rules/*.md\` | Master rule copy |
`,
    "utf-8",
  );
}

export async function syncPlatformFiles(projectRoot, platforms, packageRoot) {
  const sourceRulesDir = path.join(packageRoot, "files", "rules");
  const sourceCommandsDir = path.join(packageRoot, "files", "commands");

  const rules = await listMdcFiles(sourceRulesDir);
  const commands = await listMdcFiles(sourceCommandsDir);
  const bundle = buildBundledMarkdown(rules, commands);

  for (const platform of platforms) {
    if (platform === "cursor") await syncCursor(projectRoot, rules, commands);
    if (platform === "claude") await syncClaude(projectRoot, rules, commands);
    if (platform === "gemini") await syncGemini(projectRoot, bundle);
    if (platform === "openai") await syncOpenAi(projectRoot, rules, commands, bundle);
  }
}

export async function detectInstalledPlatforms(projectRoot) {
  const platforms = [];

  if (await fs.pathExists(path.join(projectRoot, ".cursor"))) {
    platforms.push("cursor");
  }

  if (await fs.pathExists(path.join(projectRoot, ".claude"))) {
    platforms.push("claude");
  }

  const geminiMd = path.join(projectRoot, "GEMINI.md");
  if (await fs.pathExists(geminiMd)) {
    const text = await fs.readFile(geminiMd, "utf-8");
    if (text.includes(MARKER_START)) platforms.push("gemini");
  }
  const geminiDir = path.join(projectRoot, ".gemini");
  if (!platforms.includes("gemini") && (await fs.pathExists(geminiDir))) {
    const entries = await fs.readdir(geminiDir);
    if (entries.some((n) => n.endsWith(".mdc"))) platforms.push("gemini");
    const metaReadme = path.join(geminiDir, "README.md");
    if (await fs.pathExists(metaReadme)) {
      const text = await fs.readFile(metaReadme, "utf-8");
      if (text.includes("AI-SDLC")) platforms.push("gemini");
    }
  }

  const agentsMd = path.join(projectRoot, "AGENTS.md");
  if (await fs.pathExists(agentsMd)) {
    const text = await fs.readFile(agentsMd, "utf-8");
    if (text.includes(MARKER_START)) platforms.push("openai");
  }
  const openAiDir = path.join(projectRoot, ".openai");
  if (!platforms.includes("openai") && (await fs.pathExists(openAiDir))) {
    platforms.push("openai");
  }

  return [...new Set(platforms)];
}

export async function readConfiguredPlatformsFromProject(projectRoot) {
  const configPath = path.join(projectRoot, "docs/config.yaml");
  if (!(await fs.pathExists(configPath))) return null;
  const text = await fs.readFile(configPath, "utf-8");
  return readConfiguredPlatforms(text);
}

/** Config `platforms:` first, then filesystem detection. */
export async function resolvePlatformsForUpdate(projectRoot) {
  const configured = await readConfiguredPlatformsFromProject(projectRoot);
  if (configured?.length) return configured;
  const detected = await detectInstalledPlatforms(projectRoot);
  if (detected.length) return detected;
  return null;
}
